                    $this->combinationRepository->updateCombinationOutOfStockType(
                        $productId,
                        $outOfStockType,
                        ShopConstraint::shop($shopId->getValue())
                    );
                }
            } else {
                $this->combinationRepository->updateCombinationOutOfStockType($productId, $outOfStockType, $shopConstraint);
            }
